import sys,collections,heapq,itertools,functools,bisect
def solve(data):
    v=data.split();h,w=map(int,v[:2]);a=v[2:]
    def f(x,y,mask):
        if a[x][y]=="#":return 0
        if x==h-1 and y==w-1:return 1
        mask|=1<<(x*w+y);ans=0
        for u,v in [(x+1,y),(x-1,y),(x,y+1),(x,y-1)]:
            if 0<=u<h and 0<=v<w and not(mask>>(u*w+v)&1):ans+=f(u,v,mask)
        return ans
    return f(0,0,0)

if __name__=="__main__":
    a=solve(sys.stdin.buffer.read().decode())
    print(" ".join(map(str,a)) if isinstance(a,(list,tuple)) else a)
